xtQuest=6147,starts={{kind="npc",id=11878,name="Nathanos Blightcaller",spots={{map=1423,x=0.2223,y=0.6351}}}},ends={{kind="npc",id=11898,name="Crusader Lord Valdelmar",spots={{map=1423,x=0.7521,y=0.7117}}}},objectives={{kind="item",id=13852,name="The Grand Crusader's Command",count=0}},text="Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar."},[6147]={id=6147,title="Return to Nathanos",level=60,minLevel=56,map=1423,zone="Eastern Plaguelands",raceMask=8589934770,classMask=0,faction="Horde",requiresAny={6146},nextQuest=6148,starts={{kind="npc",id=11898,name="Crusader Lord Valdelmar",spots={{map=1423,x=0.7521,y=0.7117}}}},ends={{kind="npc",id=11878,name="Nathanos Blightcaller",spots={{map=1423,x=0.2223,y=0.6351}}}},text="Return to Nathanos Blightcaller with the new information.\n",flags=8},[6148]={id=6148,title="The Scarlet Oracle, Demetria",level=60,minLevel=56,map=1423,zone="Eastern Plaguelands",raceMask=8589934770,classMask=0,faction="Horde",requiresAny={6147},starts={{kind="npc",id=11878,name="Nathanos Blightcaller",spots={{map=1423,x=0.2223,y=0.6351}}}},ends={{kind="npc",id=11878,name="Nathanos Blightcaller",spots={{map=1423,x=0.2223,y=0.6351}}}},objectives={{kind="npc",id=12339,name="Demetria",count=0,spots={{map=1423,x=0.633,y=0.6722}}}},text="The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed."},[6161]={id=6161,title="Claim Rackmore's Treasure!",level=36,minLevel=30,map=1443,zone="Desolace",raceMask=0,classMask=0,starts={{kind="object",id=177787,name="Rackmore's Log",spots={{map=1443,x=0.3607,y=0.3041}}}},ends={{kind="object",id=177786,name="Rackmore's Chest",spots={{map=1443,x=0.3,y=0.0871}}}},objectives={{kind="item",id=15878,name="R