{6281},nextQuest=6285,starts={{kind="npc",id=1323,name="Osric Strang",spots={{map=1453,x=0.7717,y=0.6099}}}},ends={{kind="npc",id=352,name="Dungar Longdrink",spots={{map=1453,x=0.7129,y=0.7223}}}},text="Bring Osric's Crate to Dungar Longdrink the gryphon master."},[6281]={id=6281,title="Continue to Stormwind",level=10,minLevel=10,map=1436,zone="Westfall",raceMask=1,classMask=0,faction="Alliance",requiresAny={6181},nextQuest=6261,starts={{kind="npc",id=523,name="Thor",spots={{map=1436,x=0.5655,y=0.5264}}}},ends={{kind="npc",id=1323,name="Osric Strang",spots={{map=1453,x=0.7717,y=0.6099}}}},text="Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind."},[6282]={id=6282,title="Harpies Threaten",level=26,minLevel=18,map=1442,zone="Stonetalon Mountains",raceMask=8589934770,classMask=0,faction="Horde",nextQuest=6283,starts={{kind="npc",id=11860,name="Maggran Earthbinder",spots={{map=1442,x=0.472,y=0.6116}}}},ends={{kind="npc",id=11860,name="Maggran Earthbinder",spots={{map=1442,x=0.472,y=0.6116}}}},objectives={{kind="npc",id=4022,name="Bloodfury Harpy",count=0,spots={{map=1442,x=0.3093,y=0.5923}}},{kind="npc",id=4025,name="Bloodfury Ambusher",count=0,spots={{map=1442,x=0.2964,y=0.6262}}},{kind="npc",id=4024,name="Bloodfury Slayer",count=0,spots={{map=1442,x=0.2679,y=0.6953}}},{kind="npc",id=4023,name="Bloodfury Roguefeather",count=0,spots={{map=1442,x=0.293,y=0.7031}}}},text="Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",flags=8},[6283]={id=6283,title="Bloodfury Bloodline",level=26,minLevel=18,map=1442,zone="Stonetalon Mountains",raceMask=8589934770,classMask=0,faction="Horde",requiresAny={6282},starts={{kind="npc",id=11860,name="Maggran Earthbinder",spots={{map=1442,x=0.472,y=0.6116}}}},ends={{kind="npc",id=11860,name="Maggran Earthbinder",spots={{map=1442,x=0.472,y=0.6116}}}},objectives={{kind="item",id=16190,name="Bloodfury Ripper's Remains",count=0,spots={{map=1442,x=0.3075,y=0.6191}}}},text="Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.",flags=8},[6284]={id=6284,title="Arachnophobia",level=21,minLevel=15,map=1442,zone="Stonetalon Mountains",raceMask=8589934770,classMask=0,faction="Horde",starts={{kind="object",id=177904,name="Wanted Poster: Besseleth",spots={{map=1442,x=0.5906,y=0.7571}}}},ends={{kind="npc",id=11860,name="Maggran Earthbinder",spots={{map=1442,x=0.472,y=0.6116}}}},objectives={{kind="item",id=16192,name="Besseleth's Fang",count=0,spots={{map=1442,x=0.52,y=0.738}}}},text="Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.",flags=8},[6285]={id=6285,title="Return to Lewis",level=10,minLevel=10,map=1436,zone="Westfall",raceMask=1,classMask=0,faction="Alliance",requiresAny={6261},starts={{kind="npc",id=352,name="Dungar Longdrink",spots={{map=1453,x=0.7129,y=0.7223}}}},ends={{kind="npc",id=491,name="Quartermaster Lewis",spots={{map=1436,x=0.57,y=0.4717}}}},text="Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill."},[6301]={id=6301,title="Cycle of Rebirth",level=23,minLevel=17,map=1442,zone="Stonetalon Mountains",raceMask=8589934770,classMask=0,faction="Horde",nextQuest=6381,starts={{kind="npc",id=11864,name="Tammra Windfield",spots={{map=1442,x=0.4746,y=0.5838}}}},ends={{kind="npc",id=11864,name="Tammra Windfield",spots={{map=1442,x=0.4746,y=0.5838}}}},objectives={{kind="item",id=16205,name="Gaea Seed",count=0,spots={{map=1442,x=0.4974,y=0.4511}}}},text="Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.",flags=8},[6321]={id=6321,title="Supplying the Sepulcher",level=10,minLevel=10,map=1421,zone="Silverpine Forest",raceMask=16,classMask=0,faction="Horde",nextQuest=6323,starts={{kind="npc",id=6389,name="Deathguard Podrig",spots={{map=1421,x=0