",raceMask=8589934770,classMask=0,faction="Horde",requiresAny={6964},starts={{kind="npc",id=13417,name="Sagorne Creststrider",spots={{map=1454,x=0.3866,y=0.3592}}}},ends={{kind="npc",id=3057,name="Cairne Bloodhoof",spots={{map=1456,x=0.603,y=0.5168}}}},text="Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff."},[7062]={id=7062,title="The Reason for the Season",level=60,minLevel=10,map=1455,zone="Ironforge",raceMask=4294967373,classMask=0,faction="Alliance",nextQuest=7063,starts={{kind="npc",id=1365,name="Goli Krumn",spots={{map=1455,x=0.3026,y=0.5938}}}},ends={{kind="npc",id=2916,name="Historian Karnik",spots={{map=1455,x=0.7754,y=0.1182}}}},text="Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.",flags=8},[7063]={id=7063,title="The Feast of Winter Veil",level=60,minLevel=10,map=1455,zone="Ironforge",raceMask=4294967373,classMask=0,faction="Alliance",requiresAny={7062},starts={{kind="npc",id=2916,name="Historian Karnik",spots={{map=1455,x=0.7754,y=0.1182}}}},ends={{kind="npc",id=2784,name="King Magni Bronzebeard",spots={{map=1455,x=0.3909,y=0.562}}}},text="Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge."},[7064]={id=7064,title="Corruption of Earth and Seed",level=51,minLevel=45,map=280,zone="Other",raceMask=8589934770,classMask=0,faction="Horde",exclusive={7065},starts={{kind="npc",id=13699,name="Selendra",spots={{map=1443,x=0.2687,y=0.7767}}}},ends={{kind="npc",id=13699,name="Selendra",spots={{map=1443,x=0.2687,y=0.7767}}}},objectives={{kind="npc",id=12201,name="Princess Theradras",count=0}},text="Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.",dungeon="Maraudon",flags=8},[7065]={id=7065,title="Corruption of Earth and Seed",level=