"},[97420]={id=97420,title="Reduce, Reuse, Reconcile",level=36,minLevel=31,map=1434,zone="Stranglethorn Vale",raceMask=4294967373,classMask=0,faction="Alliance",starts={{kind="npc",id=2687,name="Gnaz Blunderflame",spots={{map=1434,x=0.5098,y=0.3521}}}},ends={{kind="npc",id=2687,name="Gnaz Blunderflame",spots={{map=1434,x=0.5098,y=0.3521}}}},objectives={{kind="item",id=277986,name="Drum of Crude Oil",count=0,spots={{map=1434,x=0.2863,y=0.076}}}},text="Acquire 4 Drums of Crude Oil from the Venture Co. operations at Lake Nazferiti, then return to Knaz Blunderflame in Stranglethorn Vale."},[97446]={id=97446,title="Your First Riding Kodo",level=40,minLevel=40,map=1442,zone="Stonetalon Mountains",raceMask=32,classMask=0,faction="Horde",exclusive={95511,96982,96989,96994,96996,96997,97017,97045,97046,97171,98166,99326},text="Inspect the riding kodos to choose your first mount."},[97447]={id=97447,title="An Earnest Proposition",level=60,minLevel=58,map=1455,zone="Ironforge",raceMask=4294967373,classMask=0,faction="Alliance",text="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of the Elements to Deliana in Ironforge."},[97453]={id=97453,title="Weed Whacked",level=38,minLevel=33,map=1434,zone="Stranglethorn Vale",raceMask=8589934770,classMask=0,faction="Horde",starts={{kind="npc",id=269166,name="Gemmil",spots={{map=1434,x=0.3277,y=0.2843}}}},ends={{kind="npc",id=1148,name="Nerrist",spots={{map=1434,x=0.327,y=0.2923}}}},objectives={{kind="npc",id=269175,name="Carnivorous Weed",count=0,spots={{map=1434,x=0.3137,y=0.2267}}}},text="Slay 6 Carnivorous Weeds south of Grom'gol and then inform Gemmil's mother."},[97485]={id=97485,title="Traditions of the Bluff",level=10,minLevel=3,map=1456,zone="Thunder Bluff",raceMask=8589934770,classMask=0,faction="Horde",sourceItems={278079,278080,278081,278083},starts={{kind="npc",id=269068,name="Eylah Sunhorn",spots={{map=1456,x=0.38,y=0.559}}}},ends={{kind="npc",id=269068,name="Eylah Sunhorn",spots={{map=1456,x=0.38,y=0.559}}}},objectives={{kind="object",id=665373,name="Incense Burner",count=0,spots={{map=1456,x=0.5302,y=0.8784}}},{kind="item",id=278078,name="Prepared Incense",count=0}},text="Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\n\nCombine the items and sprinkle the incense off of Hunter's Rise."},[97530]={id=97530,title="Dunemaul Dues",level=47,minLevel=40,map=1446,zone="Tanaris",raceMask=0,classMask=0,starts={{kind="npc",id=7882,name="Security Chief Bilgewhizzle",spots={{map=1446,x=0.6706,y=0.2389}}}},ends={{kind="npc",id=7882,name="Security Chief Bilgewhizzle",spots={{map=1446,x=0.6706,y=0.2389}}}},objectives={{kind="item",id=278186,name="Brilliantly Polished Bangle",count=0,spots={{map=1446,x=0.4054,y=0.734},{map=1446,x=0.4104,y=0.7265},{map=1446,x=0.4103,y=0.7123}}}},text="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to recover a particularly shiny bangle bracelet lost near the Dunemaul ogre compound."},[97534]={id=97534,title="Gritty Business",level=45,minLevel=40,map=1446,zone="Tanaris",raceMask=8589934770,classMask=0,faction="Horde",exclusive={97536},starts={{kind="npc",id=11756,name="Quinn",spots={{map=1446,x=0.5112,y=0.2788}}}},ends={{kind="npc",id=11756,name="Quinn",spots={{map=1446,x=0.5112,y=0.2788}}}},objectives={{kind="item",id=278191,name="Desert Debris",count=0}},text="Quinn wants you to recover 7  pieces of Desert Debris and return to her in Gadgetzan."},[97536]={id=97536,title="Gnomish Garbage",level=45,minLevel=40,map=1446,zone="Tanaris",raceMask=4294967373,classMask=0,faction="Alliance",exclusive={97534},starts={{kind="npc",id=14743,name="Jhordy Lapforge",spots={{map=1446,x=0.523,y=0.2689}}}},ends={{kind="npc",id=14743,name="Jhordy Lapforge",spots={{map=1446,x=0.523,y=0.2689}}}},text="Jhordy Lapforge wants you to return to him after you have dumped the Crate of Radioactive Refuse in the desert of Tanaris a safe distance away from Gadgetzan and other trash."},[97538]={id=97538,title="Pigments for Paints",level=26,minLevel=20,map=1442,zone="Stonetalon Mountains",raceMask=8589934770,classMask=0,faction="Horde",starts={{kind="npc",id=3024,name="Tah Winterhoof",spots={{map=1456,x=0.5414,y=0.4705}}}},ends={{kind="npc",id=3024,name="Tah Winterhoof",spots={{map=1456,x=0.5414,y=0.4705}}}},objectives={{kind="item",id=278201,name="Mirkweed Pods",count=0,spots={{map=1442,x=0.469,y=0.393},{map=1442,x=0.471,y=0.402}}}},text="Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake."},[97539]={id=97539,title="Silky Sutures",level=36,minLevel=30,map=1417,zone="Arathi Highlands",raceMask=8589934770,classMask=0,faction="Horde",nextQuest=92519,starts={{kind="npc",id=12920,name="Doctor Gregory Victor",spots={{map=1417,x=0.7341,y=0.3689}}}},ends={{kind="npc",id=12920,name="Doctor Gregory Victor",spots={{map=1417,x=0.7341,y=0.3689}}}},objectives={{kind="item",id=278225,name="Surgical Spidersilk",count=0,spots={{map=1417,x=0.1992,y=0.5465},{map=1417,x=0.4294,y=0.3255}}}},text="Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands."},[97558]={id=97558,title="Hides for the Forsaken",level=11,minLevel=6,map=1420,zone="Tirisfal Glades",raceMask=8589934770,classMask=0,faction="Horde",starts={{kind="npc",id=3549,name="Shelene Rhobart",spots={{map=1420,x=0.6543,y=0.6012}}}},ends={{kind="npc",id=3549,name="Shelene Rhobart",spots={{map=1420,x=0.6543,y=0.6012}}}},objectives={{kind="item",id=278242,name="Duskbat Wing Membrane",count=0,spots={{map=1420,x=0.4171,y=0.5742},{map=1420,x=0.7191,y=0.3374}}},{kind="item",id=278243,name="Darkhound Hide",count=0,spots={{map=1420,x=0.3864,y=0.4026},{map=1420,x=0.6827,y=0.3071}}},{kind="item",id=278244,name="Vile Fin Murloc Skin",count=0,spots={{map=1420,x=0.7513,y=0.2654},{map=1420,x=0.7006,y=0.2497}}}},text="Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin."},[97583]={id=97583,title="WRIGGLE.",level=1,minLevel=1,map=1458,zone="Undercity",raceMask=8589934770,classMask=0,faction="Horde",starts={{kind="npc",id=269452,name="Excitable Slime",spots={{map=1458,x=0.5727,y=0.6497}}}},ends={{kind="npc",id=269452,name="Excitable Slime",spots={{map=1458,x=0.5727,y=0.6497}}}},objectives={{kind="item",id=278265,name="Nutritious Slime Sludge",count=0}},text="Purchase Nutritious Slime Sludge and return to your befriended excitable slime. If it seems tired, try dancing with it again to catch its attention."},[97617]={id=97617,title="Safety Checks",level=40,minLevel=35,map=1418,zone="Badlands",raceMask=4294967373,classMask=0,faction="Alliance",starts={{kind="npc",id=269577,name="Dorgaron",spots={{map=1418,x=0.5463,y=0.1287}}}},ends={{kind="npc",id=269577,name="Dorgaron",spots={{map=1418,x=0.5463,y=0.1287}}}},objectives={{kind="item",id=278402,name="Unstudied Artifact",count=0,spots={{map=1418,x=0.5243,y=0.3119},{map=1418,x=0.5376,y=0.3231},{map=1418,x=0.4966,y=0.6431}}},{kind="item",id=278403,name="Explorers' League Mining Helmet",count=0},{kind="item",id=278404,name="Pristine Mattock",count=0}},text="Recover 8 Unstudied Artifacts, an Explorers' League Mining Helmet, and a Pristine Mattock and bring them to Dorgaron at the border of Loch Modan and the Badlands."},[97884]={id=97884,title="Armory of Sunnyglade",level=40,minLevel=36,map=2548,zone="Riverglades",raceMask=8589934770,classMask=0,faction="Horde",starts={{kind="npc",id=5819,name="Mirelle Tremayne",spots={{map=1458,x=0.6164,y=0.2895}}}},ends={{kind="npc",id=5819,name="Mirelle Tremayne",spots={{map=1458,x=0.6164,y=0.2895}}}},objectives={{kind="item",id=278868,name="Tremayne Family Blacksmithing Techniques",count=0}},text="Travel to Sunnyglade in the Riverglades and recover the tome of Tremayne Family Blacksmithing Techniques."},[97891]={id=97891,title="Prompt Potion Runner",level=16,minLevel=9,map=1458,zone